CREATE TABLE IF NOT EXISTS ai_evaluations(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,ai_run_id UUID REFERENCES ai_runs(id) ON DELETE SET NULL,reviewer_id UUID REFERENCES users(id) ON DELETE SET NULL,rating TEXT NOT NULL CHECK(rating IN ('good','bad','needs_improvement')),category TEXT,feedback TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT now());CREATE INDEX IF NOT EXISTS ai_eval_tenant_idx ON ai_evaluations(tenant_id,created_at DESC);